10: export class App implements OnInit, OnDestroy {
11:   protected readonly title = signal('reportes-mf');
12: 
13:   private readonly handleLanguageChange = (event: Event): void => {
14:     const lang = (event as CustomEvent<{ answer?: string }>).detail?.answer;
15:     this.useLanguage(lang);
16:   };
17: 
18:   constructor(
19:     private readonly translate: TranslateService,
20:     private readonly applicationRef: ApplicationRef,
21:   ) {}
22: 
23:   ngOnInit(): void {
24:     this.useLanguage(getCookie('lang') ?? 'es');
25:     window.addEventListener('lang', this.handleLanguageChange);
26:   }
27: 
28:   ngOnDestroy(): void {
29:     window.removeEventListener('lang', this.handleLanguageChange);
30:   }
31: 
32:   private useLanguage(lang?: string): void {
33:     if (!lang) {
34:       return;
35:     }
36: 
37:     this.translate.use(lang).subscribe(() => {
38:       this.applicationRef.tick();
39:     });
40:   }
41: }
42: 
43: function getCookie(name: string): string | undefined {
44:   const value = `; ${document.cookie}`;
45:   const parts = value.split(`; ${name}=`);
46: 
47:   if (parts.length === 2) {
48:     return parts.pop()?.split(';').shift();
49:   }
50: 
51:   return undefined;
52: }

