29:   private async initializeUser() {
30:     try {
31:       const payload = this.autenticationService.getPayload();
32:       const docIdentificacion = await this.autenticationService.getDocument();
33:       const usuarioWSO2 = payload.sub || null;
34:       const correoUsuario = payload.email || null;
35:   
36:       let foundId = false;
37:   
38:       if (docIdentificacion) {
39:         foundId = await this.findByDocument(docIdentificacion, usuarioWSO2, correoUsuario);
40:       }
41:       if (usuarioWSO2 && !foundId) {
42:         foundId = await this.findByUserEmail(usuarioWSO2);
43:       }
44:       if (correoUsuario && !foundId) {
45:         await this.findByUserEmail(correoUsuario);
46:       }
47:     } catch (error) {
48:       console.error('Error inicializando usuario (core): ', error)
49:     }
50:     
51:   }
52: 
53:   private findByDocument(docIdentificacion: string, usuario: string | null, correo: string | null): Promise<boolean> {
54:     return new Promise<boolean>((resolve, reject) => {
55:       this.anyService.get(path, `datos_identificacion?query=Activo:true,Numero:${docIdentificacion}&sortby=FechaCreacion&order=desc`)
56:         .subscribe((res: any) => {
57:           if (res && res.length && Object.keys(res[0]).length > 0) {
58:             this.user = this.extractTercero(res, usuario, correo) || res[0].TerceroId;
59:             if (this.user) {
60:               this.user.Documento = docIdentificacion;
61:               this.updateUser(this.user);
62:               resolve(true);
63:             } else {
64:               resolve(false);
65:             }
66:           } else {
67:             resolve(false);
68:           }
69:         }, (error) => {
70:           reject(false);
71:         });
72:     });
73:   }
74: 
75:   private findByUserEmail(userEmail: string): Promise<boolean> {
76:     return new Promise<boolean>((resolve, reject) => {
77:       this.anyService.get(path, `tercero?query=UsuarioWSO2:${userEmail}`)
78:         .subscribe((res: any) => {
79:           if (res && res.length && Object.keys(res[0]).length > 0) {
80:             this.user = res[0];
81:             this.updateUser(this.user);
82:             resolve(true);
83:           } else {
84:             resolve(false);
85:           }
86:         }, (error) => {
87:           reject(false);
88:         });
89:     });
